def visibility(w):
    if w=='WF47': return 'Submitter: own case/status/replies only. Selected eligible reviewers: exact case plus Review; sensitive contents require ViewSensitive; named identity requires ViewIdentity. Unselected office/priest/bishop/admin/leader/guardian: no case, count or existence signal.'
    if w=='WF35': return 'Reporter and assigned incident handlers only; guardian receives reviewed own-child disclosure, excluding third-party statements. Ordinary office, leaders, clergy and bishops receive nothing solely from rank.'
    if w in {'WF48','WF63'}: return 'Author only by default. WF48: only explicit task/current-priest share gives named eligible readers access; assignee must see that task. WF63: account author only. Successor/bishop/admin/guardian has no inherited content right.'
    if w in FINANCE: return 'Entry/approval/payment/reconciliation roles see only granted financial scope; donor identity is a separate grant. Applicant/payer sees own permitted receipts/balance; guardian/household adult has no automatic donor access. Leaders and ordinary office have no full Finance projection.'
    if w=='WF51': return 'Every visitor sees published approved fields only. No person records, unpublished clergy contacts, private events, request statuses, participant lists or precise visitor-location logs.'
    if w in PUBLIC: return 'Editors/reviewers see permitted draft/revision; public/member/group audience sees only the approved published revision and its permitted files. A public event/content item does not publish linked private people or evidence.'
    if w in APPLICANT: return 'Applicant/verified guardian or representative: own purpose-scoped projection and explicitly released output. Office: preparation/coordination subset. Priest: assigned clergy decision fields. Bishop: only separately required decision/oversight grant. Leader: own assigned group/event subset. No unrelated donor, medical, pastoral or concern content.'
    return 'Assigned owner/operators see exact permitted parish/group/record scope. Applicant/guardian receives only their own authorized projection if involved. Clergy/bishop/admin access is field/action-specific; leadership, rank and combined views do not broaden it. Search/exports/counts apply the same restrictions.'

def transitions(w):
    wid,title,entry,data,seq,actor_text,gates,owner,exceptions,end,sections=w
    states=seq.split(' > '); actors=actor_text.split(';')
    assert len(actors) in {len(states),len(states)-1},(wid,len(states),len(actors))
    rows=[]
    for i in range(1,len(states)):
        actor=actors[i] if len(actors)==len(states) else actors[i-1]
        label=states[i]
        if label.lower().startswith('awaiting'): label='Submit for '+label[9:]
        else: label='Record '+label
        rows.append(dict(id=f'{wid}-T{i:02}',source=states[i-1],action=label,actor=actor,target=states[i],gate=gates,effect=f'Commit {states[i]} for the exact owning record and revision; preserve prior state/actual actor/time; update related references specified in the completion rule; emit {wid}-T{i:02} once.'))
    if wid not in NO_BRANCH:
        review_states=' / '.join(states[:-1])
        cancel_states=' / '.join(s for s in states[:-1] if not re.search(r'signed|posted|paid|registered|reconciled|issued|collected|celebrated|actually|occurred|completed|checked out|returned|receipt verified|allocated|receipts allocated',s,re.I)) or 'An explicitly pending correction/request before irreversible action'
        rows += [
        dict(id=wid+'-T90',source=review_states,action='Request correction / Return for information',actor=owner+' (eligible reviewer for this exact stage)',target='Returned / Needs information',gate='Only fields still legally/operationally reviewable at the selected listed source state; identify exact field/document and saved resume state. No return action overwrites signed/posted/official facts; those use amendment/reversal. Separate applicant explanation from private notes.',effect='Keep entered facts and prior decisions; assign supplier; record required item, useful reason and exact prior review state to resume.'),
        dict(id=wid+'-T91',source='Returned / Needs information',action='Submit corrected information',actor='Permitted applicant/supplier or attributed office recorder',target='Prior review stage, rechecked',gate='Revalidate supplied fields/documents, authority and revision; correction cannot inherit an invalid signature or stale consent.',effect='Preserve previous version; reopen only applicable review; notify exact current owner.'),
        dict(id=wid+'-T92',source=cancel_states,action='Withdraw / Decline / Cancel',actor='Applicant for unhandled own request only; otherwise '+owner+' within deciding authority',target='Withdrawn / Declined / Cancelled',gate='Choose actual outcome and reason; preview dependent holds, payments, files and people. Cancelling an unperformed request never cancels actual receipt/payment/celebration. Terminal/official/posted facts use their separate review/correction flow.',effect='Stop future new work/reminders; release only unneeded provisional resources; retain history; create explicit refund/review task rather than claim money returned.'),
        dict(id=wid+'-T93',source=states[-1]+' / Cancelled / Returned, only where reviewed correction is permitted',action='Request reviewed reopening / correction',actor=owner+' and actual competent approver',target='Reopened review, not restored approval',gate='Permission, retention and domain policy permit; signed/official/posted results are amended or replaced, never erased; recheck current availability/eligibility.',effect='New attributed history and current owner; prior outcomes stay visible; downstream approvals require their own fresh conditions.')]
    return rows

def render_workflows():
    lines=['# Workflow specifications','',
    'All cards describe proposed behavior; referenced owner directions remain as identified in [answers](answers.md). These are specifications, not implemented state machines or executed tests. Every transition uses an authenticated eligible actor or the expressly limited applicant/guest route; server-side scope/revision/idempotency checks remain required even when controls are hidden.', '',
    '## Shared transaction and timing contract','',
    'A meaningful state transition has one operation ID, expected source state/revision, exact owning parish/record, actual actor and responsible authority. Retry first queries that operation; a lost response means outcome unknown until checked. Commit primary facts atomically; a failed secondary attachment/notification creates persistent partial-result status and retries only that component. Internal instruction time, original historical event time and actual system entry time remain distinct.', '',
    'Every card inherits [proposed operational defaults](open-inputs-and-conflicts.md#operational-defaults). Office worklists are reviewed once each working day; an overdue task routes to its named lead, then competent priest/authority. This is an internal proposal, not a promised applicant SLA. No background reminders/expiry messages are described as delivered without a real runner. Expiry/permission/availability eligibility is evaluated again on protected actions even if a reminder was missed.', '',
    'Terminal results cannot use ordinary cancel/delete. Their correction/reversal/withdrawal-of-access procedure must preserve the original. A returned item resumes review; it never revives an invalid signature, prior capacity hold or old grant. Where a card includes a reactivation/reopen cycle, the new cycle gets fresh checks and audit.', '',
    '## Journey index','',table(['ID','Retained journey','Sections','Forms'],[(f'[{w[0]}](#{w[0].lower()})',w[1],w[-1],', '.join(f'[{f}](field-dictionary.md#{f.lower()})' for f in FORM_MAP[w[0]])) for w in WORKFLOWS]),'']
    alltrans=[]
    for w in WORKFLOWS:
        wid,title,entry,data,seq,acts,gates,owner,exceptions,end,sections=w
        ts=transitions(w);alltrans+=ts
        if wid in NO_BRANCH: branch='Unavailable/permission/network states preserve only authorized context; no fictitious decline/financial reversal state. See specific recovery below.'
        else: branch='T90–T93 below define returned-information, resubmission, refusal/cancellation and reviewed correction/reopen branches; only states whose domain permits that branch are eligible. Signed/posted/official terminal states use amendment/reversal, never ordinary cancellation.'
        lines += [f'## {wid}', '',f'**{title}** — {sections}. Detailed field binding: '+', '.join(f'[{f}](field-dictionary.md#{f.lower()})' for f in FORM_MAP[wid])+'.', '',
        table(['Card requirement','Proposed behavior'],[
        ('Entry and trigger',entry),('Data',data+' Required/conditional fields, unknown handling and privacy are enumerated in the linked form.'),
        ('Lifecycle',seq+'. '+branch),('Transitions','Each numbered row below gives source/action/actor/prerequisite/confirmation/result. Shared transaction contract applies to every row, not only the happy path.'),
        ('Visibility',visibility(wid)),('Ownership and time',owner+' Absent operator is replaced only by an eligible scoped appointee; private case/note rights never move with an ordinary handover. Daily worklist review and defined expiry deadlines apply; no invented always-online promise.'),
        ('Corrections and exceptions',exceptions+' Wrong parish/role or revoked access stops next protected operation; no draft may migrate records across scope. A failed response is checked before retry.'),
        ('Communication',f'One explicit row for every transition in [notification matrix](notification-matrix.md#{wid.lower()}); private explanations stay in permitted secure record. No external delivery inferred.'),
        ('End result',end+' Parent case retains canonical reference and related record links. Only permitted outputs are printable/exportable under P matrix and document rules.'),
        ('Acceptance',f'{wid}-AC1 normal: traverse the stated eligible sequence and verify the exact end result. {wid}-AC2 refusal/cancellation: stop before a final result and verify resource/money/access consequences, or exercise unavailable state for pure browsing. {wid}-AC3 correction: replace one wrong field/item and prove old version survives. {wid}-AC4 boundary: another parish/unassigned actor cannot read or mutate the record, including count/export. {wid}-AC5 interruption: drop response after commit and retry same operation; no duplicate effect, no false success. Exercise this card’s specific complication in its linked A scenarios.')]),'',
        table(['Transition','Source → action → destination','Allowed actor/scope','Prerequisite and confirmation','Committed result and audit'],[(t['id'],t['source']+' → '+t['action']+' → '+t['target'],t['actor']+'; exact card scope',t['gate']+' Confirmation names record, parish, action and responsible authority; read-only steps do not need an approval dialog.',t['effect']) for t in ts]),'']
    write('workflow-specifications.md','\n'.join(lines));write('transition-inventory.json',json.dumps(alltrans,ensure_ascii=False,indent=2))

